#!/usr/bin/env bash
# PART 2 - 50 real per-project issues (2 per project 01-25). SINGLE run, parallel xargs -P 8.
set -uo pipefail
REPO="jaikaran109/51_Web_Projects"
P="https://github.com/jaikaran109/51_Web_Projects/tree/main"
B="https://github.com/jaikaran109/51_Web_Projects/blob/main"
for l in "hacktoberfest|FF7518" "level 1|0E8A16" "level 2|FBCA04" "level 3|D93F0B" "security|000000" "accessibility|5319E7"; do n="${l%%|*}"; c="${l##*|}"; gh label create "$n" --repo "$REPO" --color "$c" >/dev/null 2>&1 || true; done
F=$(mktemp); trap 'rm -f "$F"' EXIT
Q() { printf '%s\t%s\t%s\n' "$1" "$2" "$3" >> "$F"; }
