# ---- AT-ONCE parallel push: single xargs call, 8 concurrent (not one-by-one) ----
export REPO
do_one() { line="$1"; t="${line%%$'\t'*}"; rest="${line#*$'\t'}"; l="${rest%%$'\t'*}"; b="${rest#*$'\t'}"; gh issue create --repo "$REPO" --title "$t" --label "$l" --body "$b" 2>&1 | tail -n 1; }
export -f do_one
export SHELL=/bin/bash
xargs -a "$F" -d '\n' -P 8 -I{} bash -c 'do_one "$@"' _ {}
echo "OPEN NOW: $(gh issue list --repo "$REPO" --state open --limit 200 --json number --jq length)"